```csharp
public async Task<List<PostSummary>> GetPostsByTitlePrefixAsync(
    BlogContext context,
    string prefix,
    CancellationToken cancellationToken)
{
    var postsQuery =
        from post in context.Posts
        select new PostSummary(post.PostId, post.Title);

    var allPosts = await postsQuery.ToListAsync(cancellationToken);

    var matchingPosts =
        (from post in allPosts
         where TitleRules.HasPrefix(post.Title, prefix)
         select post)
        .ToList();

    return matchingPosts;
}

