public async Task<Dictionary<int, long>> GetTotalViewsByBlogAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into blogPosts
        select new
        {
            BlogId = blogPosts.Key,
            TotalViews = blogPosts.Sum(p => (long)p.Views)
        };

    var totals = await query.ToListAsync(cancellationToken);

    return totals.ToDictionary(t => t.BlogId, t => t.TotalViews);
}
```

