public async Task UpdatePostTitleAsync(
    BlogContext blogContext,
    int postId,
    string newTitle,
    CancellationToken cancellationToken)
{
    var postQuery =
        from post in blogContext.Posts
        where post.Id == postId
        select post;

    var matchingPost = await postQuery.SingleOrDefaultAsync(cancellationToken);

    if (matchingPost == null)
    {
        throw new KeyNotFoundException($"Post {postId} was not found.");
    }

    matchingPost.Title = newTitle;

    await blogContext.SaveChangesAsync(cancellationToken);
}
```

